Lemma nullbase_xor1 : forall x, 0 <= x -> Z.lxor (Z.b2z (0 <? x)) (Z.b2z (x <? 1)) = 1.
Proof.
  intros x Hx. destruct (Z.ltb_spec 0 x); destruct (Z.ltb_spec x 1); cbn; first [reflexivity | exfalso; lia].
Qed.

