Definition SV_COPY_STACK : Z := 64.

Definition svcopy_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (sv dst src : Z) (bs : list byte) (rest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (zlength bs)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (dst, dst + zlength bs)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' sv (C8 (wz src) :: C8 (wz (zlength bs)) :: rest)
    /\ rw_cells usegs m' dst [CB (length bs) bs]
    /\ bytes_at usegs m' src bs.

Definition svcopy_stmt : Prop := forall (sv dst src : Z) (bs : list byte) (rest : list cell) (lo : Z) (junk : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m sv (C8 (wz src) :: C8 (wz (zlength bs)) :: rest) ->
  bytes_at usegs m src bs ->
  rw_cells usegs m dst [CB (length bs) junk] ->
  (src + zlength bs <= dst \/ dst + zlength bs <= src) ->
  (dst + zlength bs <= sv \/ sv + Z.of_nat (cells_size (C8 (wz src) :: C8 (wz (zlength bs)) :: rest)) <= dst) ->
  stk usegs m lo (bv_unsigned sp) -> lo + SV_COPY_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= sv ->
  (dst + zlength bs <= lo \/ bv_unsigned sp <= dst) ->
  (src + zlength bs <= lo \/ bv_unsigned sp <= src) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (svcopy_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc sv dst src bs rest lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 sv) (Z_to_bv 64 dst) (Z_to_bv 64 (zlength bs)) (Z_to_bv 64 0) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SV_COPY) fc None m (seg_rom usegs)).
